{id:'version-choice',prompt:'假设以下套餐可用，您会考虑哪一种？',type:'single',denominator:12,missing:0,choices:[{id:'option-1',label:'免费版：基础AI + 5GB',count:5},{id:'option-2',label:'标准版：19元/月，完整AI + 100GB',count:3},{id:'option-3',label:'家庭版：39元/月，最多5人 + 500GB',count:0},{id:'option-4',label:'都不选择',count:1},{id:'option-5',label:'不确定',count:3}]},
