];

var GROUP_DATA={
'西兴街道':{street:{choices:[4,0,0,0,0]},'age-range':{choices:[0,0,1,0,1,2,0]},occupation:{choices:[0,0,1,2,0,1]},household:{choices:[0,0,0,0,4]},'ai-experience':{choices:[0,2,0,0,2]},'cloud-experience':{choices:[0,2,0,0,2]},'top-features':{choices:[3,0,0,0,2,4,3]},'version-choice':{choices:[1,1,0,0,2]},'standard-price-change':{choices:[0,0,0,0,1,3]},'family-antifraud':{choices:[1,0,1,0,0,2]},privacy:{mean:4.25,median:4},'max-monthly-payment':{mean:7.25,median:5}},
'长河街道':{street:{choices:[0,4,0,0,0]},'age-range':{choices:[0,0,0,0,2,2,0]},occupation:{choices:[1,0,0,2,0,1]},household:{choices:[0,0,1,0,3]},'ai-experience':{choices:[0,1,0,3,0]},'cloud-experience':{choices:[0,2,0,2,0]},'top-features':{choices:[2,1,0,0,3,3,3]},'version-choice':{choices:[1,1,0,1,1]},'standard-price-change':{choices:[2,0,0,0,1,1]},'family-antifraud':{choices:[2,0,0,0,0,2]},privacy:{mean:4.25,median:4},'max-monthly-payment':{mean:4.75,median:0}},
'浦沿街道':{street:{choices:[0,0,4,0,0]},'age-range':{choices:[0,0,0,1,1,2,0]},occupation:{choices:[1,0,0,2,0,1]},household:{choices:[0,1,1,0,2]},'ai-experience':{choices:[0,2,0,2,0]},'cloud-experience':{choices:[0,2,1,1,0]},'top-features':{choices:[3,0,0,0,4,3,2]},'version-choice':{choices:[3,1,0,0,0]},'standard-price-change':{choices:[3,0,0,0,0,1]},'family-antifraud':{choices:[4,0,0,0,0,0]},privacy:{mean:4.5,median:4.5},'max-monthly-payment':{mean:5,median:0}}
};
var ORDER=['全部','西兴街道','长河街道','浦沿街道'];
var idx=0;

function esc(s){return String(s).replace(/[&<>"']/g,function(m){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m];});}

function choiceRow(label,count,denominator){
  return '<div class="choice"><span>'+esc(label)+'</span><span class="count">'+count+'</span><div class="bar"><span style="width:'+Math.round(count/denominator*100)+'%"></span></div></div>';
}

function renderQuestionCard(q,overall){
  var inner='<h3>'+esc(q.prompt)+'</h3><div class="denominator">有效分母：'+esc(q.denominator)+'</div>';
  if(q.type==='scale' || q.type==='number'){
    inner+='<div>均值 '+esc(q.mean)+' · 中位数 '+esc(q.median)+' '+esc(q.unit||'')+'</div>';
  }
  if(q.choices && q.choices.length){
    q.choices.forEach(function(c){
      inner+=choiceRow(c.label,c.count,q.denominator);
    });
  }
  return inner;
}

function renderOverall(){
  var html='';
  QUESTIONS.forEach(function(q){
    var attr='data-question-id="'+esc(q.id)+'"';
    html+='<div class="question" '+attr+'>'+renderQuestionCard(q,true)+'</div>';
  });
  document.getElementById('overall-stats').innerHTML=html;
}

function renderGroup(){
  var summary=document.getElementById('group-summary');
  var stats=document.getElementById('group-stats');
  var groupName=ORDER[idx];
  var valid=groupName==='全部'?12:4;
  summary.innerHTML='<span class="group-name">'+esc(groupName)+'</span>（有效数 <span class="group-valid">'+valid+'</span>）';

  if(groupName==='全部'){
    stats.innerHTML='<p>当前为全部分组，整体统计已在上方 #overall-stats 显示。</p>';
    return;
  }

  var group=GROUP_DATA[groupName];
  var html='';
  QUESTIONS.forEach(function(q){
    if(!group.hasOwnProperty(q.id)){return;}
    var token=group[q.id];
    var inner='<h3>'+esc(q.prompt)+'</h3><div class="denominator">有效分母：4</div>';
    if(q.id==='privacy' || q.id==='max-monthly-payment'){
      inner+='<div>均值 '+esc(token.mean)+' · 中位数 '+esc(token.median)+' '+esc(q.unit||'')+'</div>';
    }else if(q.choices && token.choices){
      token.choices.forEach(function(count,i){
        inner+=choiceRow(q.choices[i].label,count,4);
      });
    }
    html+='<div class="question" data-group-question-id="'+esc(q.id)+'">'+inner+'</div>';
  });
  stats.innerHTML=html;
}

renderOverall();
renderGroup();
document.getElementById('next-group').addEventListener('click',function(){
  idx=(idx+1)%ORDER.length;
  renderGroup();
});
})();
</script>
</body>
</html>",
  "notes": "修复了前版 JavaScript 语法错误问题：将 QUESTIONS 数组改为使用单引号键值，避免与 HTML 属性引号冲突；GROUP_DATA 改为对象结构并移除嵌套数组，避免解析异常。保持全部15题在 #overall-stats 中且使用唯一 data-question-id，组内统计只使用 data-group-question-id。#group-summary 只包含组名和有效数，不渲染题卡。#next-group 初始顺序为 全部→西兴→长河→浦沿，点击后按固定顺序循环。页面无任何网络依赖。"
}

